import { Link, useNavigate } from "react-router-dom";
import "./dashboard.css";

export default function Dashboard() {
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user"));

  if (!user) {
    navigate("/login");
    return null;
  }

  const logout = () => {
    localStorage.removeItem("user");
    navigate("/login");
  };

  let cards = [];

  // ROLE BASED CARDS
  if (user.role === "Admin") {
    cards = [
      { title: "Manage Students", desc: "Add / Edit / View Students", path: "/students", color: "#4f46e5", icon: "🎓" },
      { title: "Manage Instructors", desc: "Instructor control panel", path: "/instructors", color: "#8b5cf6", icon: "👨‍🏫" },
      { title: "Courses", desc: "Course management", path: "/courses", color: "#06b6d4", icon: "📚" },
      { title: "Profile", desc: "User profile", path: "/profile", color: "#f59e0b", icon: "👤" },
      { title: "Progress", desc: "Analytics & performance", path: "/progress", color: "#22c55e", icon: "📈" },
      { title: "Settings", desc: "System settings", path: "/settings", color: "#ef4444", icon: "⚙️" }
    ];
  } 
  else if (user.role === "Instructor") {
    cards = [
      { title: "My Courses", desc: "Manage your courses", path: "/courses", color: "#8b5cf6", icon: "📚" },
      { title: "Students", desc: "View students", path: "/students", color: "#10b981", icon: "🎓" },
      { title: "Settings", desc: "Account settings", path: "/settings", color: "#ef4444", icon: "⚙️" }
    ];
  } 
  else {
    cards = [
      { title: "Profile", desc: "Your details", path: "/profile", color: "#4f46e5", icon: "👤" },
      { title: "Courses", desc: "Available courses", path: "/courses", color: "#8b5cf6", icon: "📚" },
      { title: "Progress", desc: "Your performance", path: "/progress", color: "#22c55e", icon: "📈" }
    ];
  }

  return (
    <div className="dashboard-container">

      {/* HEADER */}
      <div className="header">
        <h1>RBAC Dashboard</h1>
        <h2>Welcome, {user.name}</h2>
        <p>{user.email}</p>
        <h3>
          Role: <span className="role">{user.role}</span>
        </h3>

        <button className="logout-btn" onClick={logout}>
          Logout
        </button>
      </div>

      {/* CARDS */}
      <div className="grid">
        {cards.map((card, index) => (
          <Link key={index} to={card.path} className="card-link">
            <div className="card" style={{ background: card.color }}>
              <div className="icon">{card.icon}</div>
              <h2>{card.title}</h2>
              <p>{card.desc}</p>
              <span>Open →</span>
            </div>
          </Link>
        ))}
      </div>

      {/* STATS */}
      <div className="stats">
        <div className="stat">
          <h3>15</h3>
          <p>Total Courses</p>
        </div>

        <div className="stat">
          <h3>25</h3>
          <p>Total Students</p>
        </div>

        <div className="stat">
          <h3>3</h3>
          <p>User Roles</p>
        </div>

        <div className="stat">
          <h3>98%</h3>
          <p>Performance</p>
        </div>
      </div>

    </div>
  );
}
